  const skill=sourceSkills.find(s=>s.type===(ultimate?'终结技':'战技'))||(!ultimate?sourceSkills.find(s=>s.type==='普攻'):null);
  if(skill){const r=ratio(skill.description,actor);if(r){const amount=(r.hp?hp:attack)*r.value,all=/对敌方全体|对敌方所有/.test(skill.description);for(const t of all?targets:[target])rawDamage(actor,t,amount,{toughness:ultimate?40:30});if(/相邻目标/.test(skill.description)&&!all)for(const t of targets.filter(t=>t!==target).slice(0,2))rawDamage(actor,t,amount*.5,{toughness:15});note('按原赋能倍率结算；复杂分支见二维适配说明');return true;}}
